CREATE DATABASE IF NOT EXISTS davao_local_directory CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE davao_local_directory;

CREATE TABLE roles (id TINYINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, name VARCHAR(30) NOT NULL UNIQUE);
INSERT IGNORE INTO roles (id,name) VALUES (1,'customer'),(2,'owner'),(3,'admin');
CREATE TABLE users (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, role_id TINYINT UNSIGNED NOT NULL DEFAULT 1, name VARCHAR(100) NOT NULL,
 email VARCHAR(150) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY (role_id) REFERENCES roles(id)
);
CREATE TABLE categories (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE, active BOOLEAN NOT NULL DEFAULT TRUE);
INSERT IGNORE INTO categories(name) VALUES ('Food & Beverage'),('Repair Services'),('Beauty & Wellness'),('Printing Services'),('Retail'),('Home Services'),('Automotive'),('Electronics'),('Clothing'),('Education'),('Professional Services'),('Other');
CREATE TABLE businesses (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, owner_id INT UNSIGNED NOT NULL, category_id INT UNSIGNED NOT NULL,
 name VARCHAR(150) NOT NULL, description TEXT, contact_phone VARCHAR(50) NOT NULL, contact_email VARCHAR(150), website VARCHAR(200),
 address VARCHAR(200) NOT NULL, barangay VARCHAR(80), district VARCHAR(80), city VARCHAR(80) NOT NULL DEFAULT 'Davao City',
 latitude DECIMAL(10,7), longitude DECIMAL(10,7), status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending',
 verified_at DATETIME NULL, is_verified BOOLEAN NOT NULL DEFAULT FALSE, logo_path VARCHAR(255) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 FOREIGN KEY(owner_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(category_id) REFERENCES categories(id), INDEX(status), INDEX(category_id), INDEX(city)
);
CREATE TABLE services (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE);
CREATE TABLE business_services (business_id INT UNSIGNED NOT NULL, service_id INT UNSIGNED NOT NULL, price DECIMAL(10,2) NULL, description VARCHAR(255), PRIMARY KEY(business_id,service_id), FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE, FOREIGN KEY(service_id) REFERENCES services(id) ON DELETE CASCADE);
CREATE TABLE business_hours (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, business_id INT UNSIGNED NOT NULL, day_of_week TINYINT NOT NULL, opens TIME NULL, closes TIME NULL, is_closed BOOLEAN NOT NULL DEFAULT FALSE, UNIQUE(business_id,day_of_week), FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE);
CREATE TABLE reviews (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, business_id INT UNSIGNED NOT NULL, user_id INT UNSIGNED NOT NULL, rating TINYINT NOT NULL, comment TEXT NOT NULL, response TEXT NULL, status ENUM('visible','hidden') DEFAULT 'visible', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP, UNIQUE(business_id,user_id), FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, CHECK(rating BETWEEN 1 AND 5));
CREATE TABLE favorites (user_id INT UNSIGNED NOT NULL,business_id INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,business_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE);
CREATE TABLE inquiries (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id INT UNSIGNED NOT NULL,user_id INT UNSIGNED NOT NULL,subject VARCHAR(150) NOT NULL,message TEXT NOT NULL,status ENUM('new','read','replied','closed') DEFAULT 'new',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE notifications (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,message VARCHAR(255) NOT NULL,link_url VARCHAR(255) NULL,type VARCHAR(40) NOT NULL DEFAULT 'general',is_read BOOLEAN DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX(user_id,is_read));
CREATE TABLE activity_logs (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NULL,action VARCHAR(100) NOT NULL,details VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE business_images (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id INT UNSIGNED NOT NULL,image_path VARCHAR(255) NOT NULL,caption VARCHAR(160) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE,INDEX(business_id));
CREATE TABLE business_reports (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id INT UNSIGNED NOT NULL,user_id INT UNSIGNED NOT NULL,reason ENUM('fake_business','wrong_information','inappropriate_content','duplicate_listing','closed_business','other') NOT NULL,details TEXT NULL,status ENUM('pending','reviewed','resolved','dismissed') NOT NULL DEFAULT 'pending',admin_notes TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX(status),INDEX(business_id));
CREATE TABLE review_reports (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,review_id INT UNSIGNED NOT NULL,user_id INT UNSIGNED NOT NULL,reason VARCHAR(255) NOT NULL,status ENUM('pending','reviewed','dismissed') NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(review_id) REFERENCES reviews(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,UNIQUE(review_id,user_id),INDEX(status));
CREATE TABLE business_views (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id INT UNSIGNED NOT NULL,user_id INT UNSIGNED NULL,viewed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,INDEX(business_id),INDEX(viewed_at));
CREATE TABLE appointments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id INT UNSIGNED NOT NULL,service_id INT UNSIGNED NULL,customer_id INT UNSIGNED NOT NULL,appointment_at DATETIME NOT NULL,notes TEXT NULL,status ENUM('pending','confirmed','rejected','rescheduled','completed','cancelled') NOT NULL DEFAULT 'pending',owner_notes TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE,FOREIGN KEY(service_id) REFERENCES services(id) ON DELETE SET NULL,FOREIGN KEY(customer_id) REFERENCES users(id) ON DELETE CASCADE,INDEX(business_id,appointment_at),INDEX(customer_id,status));
